greet() {
    local name="$1"        # $1 = first argument passed to the function — always 'local' it
    echo "Hello, $name"
}

greet "SOLO"                # call it like a command

# All positional parameters inside a function:
show_args() {
    echo "First: $1"
    echo "All: $@"           # each argument as a separate word
    echo "Count: $#"          # number of arguments passed
}
show_args a b c

add() {
    local result=$(( $1 + $2 ))
    echo "$result"          # "return" data by printing it
}
sum=$(add 3 4)               # capture it via command substitution
echo "$sum"                    # 7

is_even() {
    (( $1 % 2 == 0 ))          # return TRUE/FALSE as an exit code, not printed text
}
if is_even 4; then
    echo "even"
fi

#!/usr/bin/env bash
set -euo pipefail

log() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] $*"; }
error() { echo "[$(date '+%Y-%m-%d %H:%M:%S')] ERROR: $*" >&2; }

cleanup() {
    log "Cleaning up..."
    [ -n "${TMPFILE:-}" ] && rm -f "$TMPFILE"
}
trap cleanup EXIT
trap 'error "Failed on line $LINENO"' ERR

usage() {
    echo "Usage: $0 <input_file>" >&2
    exit 1
}

# --- Validate input ---
[ $# -lt 1 ] && usage
INPUT_FILE="$1"
[ ! -f "$INPUT_FILE" ] && { error "$INPUT_FILE not found"; exit 1; }

# --- Main logic ---
TMPFILE=$(mktemp)
log "Processing $INPUT_FILE..."
grep "pattern" "$INPUT_FILE" > "$TMPFILE"
log "Found $(wc -l < "$TMPFILE") matches"

log "Done."

#!/usr/sbin/nft -f

flush ruleset

table inet filter {
    chain input {
        type filter hook input priority 0; policy drop;

        ct state established,related accept
        iif lo accept

        tcp dport 22 accept
        tcp dport 80 accept
        tcp dport 443 accept

        # rate-limited SSH, same idea as the iptables example above
        tcp dport 2222 ct state new limit rate 3/minute accept

        # explicit block of a known-bad IP
        ip saddr 198.51.100.23 drop
    }

    chain forward {
        type filter hook forward priority 0; policy drop;
    }

    chain output {
        type filter hook output priority 0; policy accept;
    }
}

set allowed_ips {
    type ipv4_addr
    elements = { 203.0.113.5, 203.0.113.6, 198.51.100.10 }
}

chain input {
    type filter hook input priority 0; policy drop;
    ip saddr @allowed_ips tcp dport 22 accept
}

chain input {
    type filter hook input priority 0; policy drop;
    iif lo accept
    ct state established,related accept
    ip saddr 203.0.113.5 tcp dport 22 limit rate 3/minute accept
}

